(function(){'use strict';const dialog=document.createElement('dialog');dialog.id='heightdialog';dialog.innerHTML='<div class="stairpreviewhead"><h2>Floor heights</h2><button id="closeheights">Close</button></div><p class="small">Elevation sets the floor surface. Clear height sets its default ceiling; individual rooms can override it.</p><div id="heightrows"></div><div id="heightconflicts" role="status"></div>';document.body.append(dialog);$('closeheights').onclick=()=>dialog.close();let scope=null;
function rows(){scope=currentBuilding().id;$('heightrows').innerHTML=Object.entries(model.floors).sort((a,b)=>b[1].z-a[1].z).map(([id,f])=>`<section class="height-row"><strong>${esc(id)} · ${esc(f.name)}</strong><div class="gridfields"><label class="field"><span>Elevation · m</span><input data-height-floor="${esc(id)}" data-height-key="z" type="number" min="-150" max="150" step=".1" value="${f.z}"></label><label class="field"><span>Clear height · m</span><input data-height-floor="${esc(id)}" data-height-key="clearHeight" type="number" min=".5" max="50" step=".1" value="${f.clearHeight??3}"></label></div></section>`).join('');conflicts();}
function conflicts(){const items=window.KERN_HEIGHTS.analyze(model);$('heightconflicts').innerHTML=items.length?'<strong>'+items.length+' height conflict'+(items.length===1?'':'s')+'</strong>'+items.map(x=>'<p class="small">'+esc(x.text)+'</p>').join(''):'<p class="small">No occupied-floor height conflicts.</p>';}
function open(fid=floorId){rows();dialog.showModal();dialog.querySelector(`[data-height-floor="${fid.replace(/[^a-zA-Z0-9_-]/g,'')}"][data-height-key="clearHeight"]`)?.focus();}
function updateFloor(fid,key,value){if(!model.floors[fid]||!Number.isFinite(value)||(key==='z'?Math.abs(value)>150:value<.5||value>50)){notify('Use valid metric floor heights');return false;}commit(()=>{const f=model.floors[fid];if(key==='z'&&window.KERN_ELEVATIONS)window.KERN_ELEVATIONS.floorMove(model,fid,value);else f[key]=value;});if($('stackdialog').open){$('stackdialog').close();window.BuildingExports.openStack();}return true;}
dialog.onchange=e=>{if(scope!==currentBuilding().id){dialog.close();return;}const fid=e.target.dataset.heightFloor,key=e.target.dataset.heightKey;if(fid&&key){updateFloor(fid,key,Number(e.target.value));conflicts();}};
for(const parent of [document.querySelector('.floorproperties'),document.querySelector('.threefloorhead'),document.querySelector('#stackdialog .stairpreviewhead')]){const b=document.createElement('button');b.textContent='Heights';b.title='Edit floor elevations and clear heights';b.onclick=()=>open();parent?.append(b);}
document.addEventListener('contextmenu',e=>{const node=e.target.closest?.('[data-floor],[data-isolate3d]');if(!node)return;e.preventDefault();e.stopPropagation();open(node.dataset.floor||node.dataset.isolate3d);});
function sync(){const r=room(selected);if(r&&!$('roomheightfields')){const node=document.createElement('section');node.id='roomheightfields';node.className='height-room';const openSky=['courtyard','terrace'].includes(r.type)||r.outdoor,voidRoom=r.type==='void',locked=!!sourceFor(r);node.innerHTML=voidRoom?'<p class="small">Void: no floor or ceiling on this level. Rooms below can extend through this opening.</p>':openSky?'<p class="small">'+(r.type==='courtyard'?'Open-sky courtyard: no ceiling; covering it on another floor is flagged.':'Terrace: walkable surface with no ceiling.')+'</p>':`<label class="field"><span>Room clear height · m</span><input id="roomclearheight" type="number" min=".5" max="50" step=".1" value="${r.height??floor().clearHeight??3}" ${locked?'disabled':''}></label><label class="checklabel"><input id="roomheightdefault" type="checkbox" ${r.height===undefined?'checked':''} ${locked?'disabled':''}> Use floor default (${floor().clearHeight??3} m)</label><p class="small">Ceiling at ${((r.z??floor().z)+(r.height??floor().clearHeight??3)).toFixed(2)} m. Occupied levels above are checked for conflicts.</p>`;$('inspector').append(node);if($('roomclearheight'))$('roomclearheight').onchange=e=>{const v=Number(e.target.value);if(Number.isFinite(v)&&v>=.5&&v<=50)commit(()=>r.height=v);else notify('Use a clear height between 0.5 and 50 m');};if($('roomheightdefault'))$('roomheightdefault').onchange=e=>commit(()=>{if(e.target.checked)delete r.height;else r.height=floor().clearHeight??3;});}
if(!$('threefloorheight')){const section=document.createElement('section');section.id='threefloorheight';section.className='height-room';$('threeoptions').prepend(section);}const f=floor();$('threefloorheight').innerHTML=`<h3>${esc(floorId)} · floor height</h3><label class="field"><span>Clear height · m</span><input id="threeclearheight" type="number" min=".5" max="50" step=".1" value="${f.clearHeight??3}"></label><button id="threeeditheights">All floor heights…</button>`;$('threeclearheight').onchange=e=>updateFloor(floorId,'clearHeight',Number(e.target.value));$('threeeditheights').onclick=()=>open();}
const oldChecks=checks;checks=function(f=floor()){const fid=Object.entries(model.floors).find(([id,x])=>x===f)?.[0];return[...oldChecks(f),...window.KERN_HEIGHTS.analyze(model).filter(x=>x.floors.includes(fid))];};
window.KERN_HEIGHT_UI={sync,open,updateFloor};sync();renderChecks();
})();
